import java.util.*;import java.util.jar.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Patch24 implements Opcodes{public static void main(String[]args)throws Exception{String p="de/nevergate/city/";Map<String,byte[]> files=new LinkedHashMap<>();try(JarFile j=new JarFile(args[0])){for(var e:Collections.list(j.entries()))files.put(e.getName(),j.getInputStream(e).readAllBytes());}int updates=0;
 for(String name:List.of("BuildingPlan","ComplexPlacement","BuildingItem","economy/CityBlocks$Device")){String key=p+name+".class";ClassNode n=new ClassNode();new ClassReader(files.get(key)).accept(n,0);for(MethodNode m:n.methods){if(name.equals("BuildingPlan")&&m.name.equals("<init>")&&m.desc.equals("(L"+p+"BuildingKind;)V"))for(var i:m.instructions.toArray())if(i.getOpcode()==ICONST_5){m.instructions.set(i,new IntInsnNode(BIPUSH,6));updates++;}
 if(name.equals("ComplexPlacement")&&m.name.equals("tag"))for(var i:m.instructions.toArray())if(i.getOpcode()==ICONST_5){m.instructions.set(i,new IntInsnNode(BIPUSH,6));updates++;}
 if((name.equals("ComplexPlacement")&&m.name.equals("employees"))||(name.equals("BuildingItem")&&m.name.equals("m_6225_")))for(var i:m.instructions.toArray())if(i instanceof LdcInsnNode l&&"ng_city_layout".equals(l.cst)){var next=i.getNext();while(next!=null&&next.getOpcode()<0)next=next.getNext();if(next!=null&&next.getOpcode()==ICONST_5){m.instructions.set(next,new IntInsnNode(BIPUSH,6));updates++;}}
 }
 if(name.endsWith("$Device"))for(String method:List.of("m_5940_","m_5939_")){if(n.methods.stream().anyMatch(m->m.name.equals(method)))throw new IllegalStateException("Unexpected existing shape");MethodNode m=new MethodNode(ACC_PUBLIC,method,"(Lnet/minecraft/world/level/block/state/BlockState;Lnet/minecraft/world/level/BlockGetter;Lnet/minecraft/core/BlockPos;Lnet/minecraft/world/phys/shapes/CollisionContext;)Lnet/minecraft/world/phys/shapes/VoxelShape;",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new FieldInsnNode(GETFIELD,n.name,"mode","Ljava/lang/String;"));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,p+"DeviceShapes","shape","(Ljava/lang/String;Lnet/minecraft/world/level/block/state/BlockState;)Lnet/minecraft/world/phys/shapes/VoxelShape;",false));m.instructions.add(new InsnNode(ARETURN));n.methods.add(m);}
 ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);n.accept(w);files.put(key,w.toByteArray());}
 if(updates!=4)throw new IllegalStateException("Expected four layout markers; got "+updates);try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:files.entrySet()){out.putNextEntry(new JarEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}System.out.println("Patched four layout markers and ATM outline/collision dispatch");}}
